    def cmdJOIN(self, channels, keys=None):
        chans = channels.split(",")
        for i in range(len(chans)):
            if chans[i][0] not in self.connection.supportHelper.chanTypes:
                chans[i] = "#{}".format(chans[i])
        channels = ",".join(chans)
